const r={READY:{label:"已齐",color:"var(--ok)",tag:"success"},INCOMING_OK:{label:"在途可齐",color:"var(--wait)",tag:"warning"},INCOMING_LATE:{label:"在途延误",color:"var(--late)",tag:"danger"},SHORT:{label:"缺料",color:"var(--short)",tag:"danger"}},i={PLANNED:["已录入","info"],RELEASED:["已下达",""],ASSEMBLING:["装配中","warning"],COMPLETED:["已完工","success"],SHIPPED:["已发货","success"],CLOSED:["已关闭","info"],CANCELLED:["已取消","info"]},a={DRAFT:["草稿","info"],APPROVED:["已审核",""],CLOSED:["已完成","success"],CANCELLED:["已取消","info"]},e={OPEN:["未到货",""],PARTIAL:["部分到货","warning"],RECEIVED:["已入库","success"],CLOSED:["已关闭","info"],CANCELLED:["已取消","info"]},o={DRAFT:["草稿","info"],CONFIRMED:["已确认",""],CONVERTED:["已转采购","success"],CANCELLED:["已取消","info"]},c={PLANNED:["待开工","info"],STARTED:["加工中","warning"],DONE:["已完工","success"],CANCELLED:["已取消","info"]},S={PLANNED:["待发出","info"],SENT:["外协中","warning"],PARTIAL:["部分回厂","warning"],RETURNED:["已回厂","success"],CANCELLED:["已取消","info"]},T={DRAFT:["草稿","info"],SUBMITTED:["待审核","danger"],REJECTED:["已驳回","info"],DISPOSED:["处置中","warning"],AWAIT_REINSPECT:["待复检","warning"],REINSPECTED:["已复检",""],CLOSED:["已关闭","success"]},u={DRAFT:["草稿","info"],SUBMITTED:["待审批","warning"],APPROVED:["已批准",""],REJECTED:["已驳回","danger"],SHIPPED:["已发货","success"],CANCELLED:["已取消","info"]},D={PRODUCT:"整机",MAKE:"自制",BUY:"外购",OUTSOURCE:"外协"},A={1:"特急",2:"急",3:"普通",4:"低"},C={STOCK:"库存",LOCKED:"锁定",PO:"采购",OUTSOURCE:"外协",WO:"自制",ARRIVAL:"待检"},N={RETURN:"退货",EXCHANGE:"换货",REWORK:"返修/挑选",CONCESSION:"让步接收"},L={SUPPLEMENT:"供应商补发",CLOSE_SHORT:"按实收关闭余量"},R={SUPPLIER:"供应商",INTERNAL:"内部",LOGISTICS:"物流"};function f(n,s=2){if(n==null||n==="")return"—";const t=Number(n);return Number.isNaN(t)?n:t.toLocaleString("zh-CN",{maximumFractionDigits:s})}function O(n){return n==null?"—":"¥"+Number(n).toLocaleString("zh-CN",{minimumFractionDigits:2,maximumFractionDigits:2})}function I(n){return n?String(n).slice(0,10):"—"}function P(n){return n?String(n).replace("T"," ").slice(0,16):"—"}function E(n){if(!n)return null;const s=new Date(String(n).slice(0,10)+"T00:00:00"),t=new Date;return t.setHours(0,0,0,0),Math.round((s-t)/864e5)}function l(n){const s=E(n);return s===null?"":s===0?"今天":s===1?"明天":s===-1?"昨天":s>0?`${s} 天后`:`超 ${-s} 天`}function g(n=0){const s=new Date;return s.setDate(s.getDate()+n),s.toISOString().slice(0,10)}function U(n){return n==null?"—":Math.round(Number(n)*100)+"%"}export{T as E,r as K,e as L,D as M,i as O,A as P,N as Q,R,C as S,c as W,L as a,I as b,u as c,P as d,S as e,a as f,o as g,O as m,f as n,U as p,l as r,g as t};
